// In-memory catalog store that stands in for the product DB.
//
// Sync jobs write here; reads pull from here. Kept intentionally simple so the
// caching + tag-based invalidation behavior is what's exercised, not the
// persistence layer.

let store = [
  { id: 1, sku: 'LAP-001', name: 'Laptop', price: 999, stock: 12, status: 'active' },
  { id: 2, sku: 'PHN-002', name: 'Phone', price: 699, stock: 30, status: 'active' },
  { id: 3, sku: 'TAB-003', name: 'Tablet', price: 499, stock: 0, status: 'backorder' },
  { id: 4, sku: 'AUD-004', name: 'Headphones', price: 199, stock: 54, status: 'active' },
  { id: 5, sku: 'WCH-005', name: 'Watch', price: 299, stock: 7, status: 'active' },
]

let lastSyncedAt = null

// Simulated DB read latency. This is the query we want to avoid re-running on
// every request, which is why the unstable_cache wrapper in ./catalog sits in
// front of it.
export async function getAllProducts() {
  await new Promise((resolve) => setTimeout(resolve, 100))
  return store.map((product) => ({ ...product }))
}

export function getLastSyncedAt() {
  return lastSyncedAt
}

// Simulate pulling the latest pricing / inventory / availability from the
// upstream ERP/PIM and writing it into the local catalog. Real syncs touch
// thousands of SKUs, so this is the slow job we keep off the request path and
// run in the background instead of blocking the admin on it.
export async function syncProductsFromUpstream() {
  await new Promise((resolve) => setTimeout(resolve, 2000))

  const syncedAt = Date.now()
  store = store.map((product) => {
    const stock = Math.max(0, product.stock - 1)
    return {
      ...product,
      stock,
      status: stock === 0 ? 'backorder' : 'active',
      syncedAt,
    }
  })
  lastSyncedAt = syncedAt

  return store.length
}

