args.content:
import { unstable_cache } from 'next/cache'

import { getAllProducts, getLastSyncedAt } from './db'

// Single cached accessor for the catalog. Every view that needs product data
// should go through this so a shared, taggable cache entry backs them all.
//
// Tagged "products" so a single revalidateTag('products') refreshes every view
// that depends on the catalog at once, without re-querying the DB on each
// individual request in between.
export const getCachedCatalog = unstable_cache(
  async () => {
    const products = await getAllProducts()
    return {
      products,
      snapshotAt: Date.now(),
      lastSyncedAt: getLastSyncedAt(),
    }
  },
  ['products'],
  { tags: ['products'], revalidate: 3600 },
)

