args.newString:
// Inline Server Action. Triggered by the <form> above. It returns immediately
// so the admin can keep working; the (slow, thousands-of-SKUs) sync is scheduled
// to run after the response is flushed. The cached catalog stays briefly stale
// until the job completes, at which point updateTag('products') immediately
// invalidates every cached entry tagged "products" — across all views that
// share the catalog — so they re-fetch fresh data on the next access.
async function syncCatalogAction() {
  'use server'
  after(async () => {
    await syncProductsFromUpstream()
    updateTag('products')
  })
}

